<?php

namespace App\Http\Controllers;

use App\Models\Knowledge;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Storage;
use Symfony\Component\HttpFoundation\BinaryFileResponse;

class KnowledgeFileController extends Controller
{
    public function __invoke(Request $request, string $knowledgePath): BinaryFileResponse
    {
        $path = $knowledgePath;

        // Accept only paths generated by our upload handlers, never arbitrary disk paths.
        abort_if(str_contains($path, '..') || str_contains($path, '\\'), 404);

        $user = auth('sanctum')->user();
        $knowledge = Knowledge::visibleTo($user)
            ->where(function ($query) use ($path) {
                $query->where('file_path', $path)
                    ->orWhere('document_path', $path)
                    ->orWhere('gambar_sampul', $path)
                    ->orWhere('url_teks', $path);
            })->first();

        abort_unless($knowledge && $knowledge->canBeViewedBy($user), 404);
        $disk = Storage::disk('knowledge');
        abort_unless($disk->exists($path), 404);

        $mime = $disk->mimeType($path);
        $inline = in_array($mime, [
            'image/jpeg', 'image/png', 'image/gif', 'image/webp',
            'audio/mpeg', 'audio/wav', 'audio/x-wav', 'audio/ogg', 'audio/mp4',
            'audio/aac', 'audio/flac', 'video/mp4', 'video/webm', 'application/pdf',
        ], true);

        $response = response()->file($disk->path($path), [
            'Content-Type' => $mime ?: 'application/octet-stream',
            'X-Content-Type-Options' => 'nosniff',
            'Content-Security-Policy' => "sandbox; default-src 'none'",
            'Vary' => 'Cookie, Authorization',
        ]);
        $response->headers->set('Cache-Control', 'private, no-store, max-age=0');
        $response->setContentDisposition($inline ? 'inline' : 'attachment', basename($path));

        return $response;
    }
}
